package com.aixpertsoft.datastack.generator.gen;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;

/**
 * Where generated files go.
 * <ul>
 *   <li><b>Generated</b> files are rewritten on every run; their folders are emptied first, so nothing stale survives.</li>
 *   <li><b>Owned</b> files (subclasses, configuration) are created only if missing and never overwritten.</li>
 * </ul>
 */
public final class Output {

    public static final String GENERATED = """
            // GENERATED by datastack-generator from model.json.
            // Do not edit: this file is overwritten on every build. Put custom code in the subclass or a custom class.
            """;

    public static final String OWNED = """
            // Created once by datastack-generator. This file is yours: the generator never overwrites it.
            // Put custom code here; it survives every regeneration.
            """;

    private final Path generatedJava;
    private final Path generatedResources;
    private final Path ownedJava;
    private final Path ownedResources;

    private final List<Path> written = new ArrayList<>();
    private final List<Path> created = new ArrayList<>();
    private int kept;

    public Output(Path generatedJava, Path generatedResources, Path ownedJava, Path ownedResources) {
        this.generatedJava = generatedJava;
        this.generatedResources = generatedResources;
        this.ownedJava = ownedJava;
        this.ownedResources = ownedResources;
    }

    /** Empties the generated folders before a run. Owned folders are never touched. */
    public void clean() {
        delete(generatedJava);
        delete(generatedResources);
    }

    public void generatedJava(String pkg, String className, String body) {
        write(javaPath(generatedJava, pkg, className), "package " + pkg + ";\n\n" + body, true);
    }

    public void generatedResource(String path, String content) {
        write(generatedResources.resolve(path), content, true);
    }

    public void ownedJava(String pkg, String className, String body) {
        write(javaPath(ownedJava, pkg, className), OWNED + "package " + pkg + ";\n\n" + body, false);
    }

    public void ownedResource(String path, String content) {
        write(ownedResources.resolve(path), content, false);
    }

    public List<Path> written() {
        return written;
    }

    public List<Path> created() {
        return created;
    }

    public int kept() {
        return kept;
    }

    private static Path javaPath(Path root, String pkg, String className) {
        return root.resolve(pkg.replace('.', '/')).resolve(className + ".java");
    }

    private void write(Path file, String content, boolean overwrite) {
        try {
            if (!overwrite && Files.exists(file)) {
                kept++;
                return;
            }
            Files.createDirectories(file.getParent());
            Files.writeString(file, content, StandardCharsets.UTF_8);
            (overwrite ? written : created).add(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static void delete(Path dir) {
        if (!Files.exists(dir)) return;
        try (Stream<Path> files = Files.walk(dir)) {
            files.sorted(Comparator.reverseOrder()).forEach(p -> {
                try {
                    Files.delete(p);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            });
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
